/**
 * @vitest-environment jsdom
 *
 * Repair #18 - THE ORB SYSTEM - pins:
 *  1. Provenance: the token values in orbTokens.ts / orbTokens.css are
 *     EXACTLY the programmatic samples in orbSampled.json (generated by
 *     scripts/orb/sample_masters.py from the founder's masters).
 *  2. Indicator law (MP-11): --orb-indicator-* carry the canonical
 *     pinned hexes, defined ONCE (mode-invariant), equal to
 *     theme/planStateColors.ts PLAN_STATE_HEX - one canon.
 *  3. Geometry: the standalone files in public/brand/orb/ carry the
 *     same measured geometry + sampled fills as orbGeometry.ts.
 *  4. Assets: the hero/medallion WebPs exist (the master itself,
 *     keyed - scripts/orb/build_hero_assets.py).
 *  5. Components render the right asset per job (hero=master,
 *     small=vector reduction, past stone=rest/no glow class).
 */
import { readFileSync, statSync } from "node:fs";
import { resolve } from "node:path";
import React, { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, describe, expect, it } from "vitest";
import sampled from "./orbSampled.json";
import { ORB_ASSETS, ORB_INDICATOR, ORB_SAMPLED } from "./orbTokens";
import { GEM_O_FACETS, ORB_RING, ORB_SPHERE, WM_PATHS } from "./orbGeometry";
import { PLAN_STATE_HEX } from "../../theme/planStateColors";
import * as OrbModule from "./OrbMark";
import { OrbHero, OrbLockup, OrbMark, OrbMarkMono, OrbWordmark } from "./OrbMark";
import { FireFrame, StateStone } from "./FireLine";

const webRoot = resolve(__dirname, "../../..");
const css = readFileSync(resolve(webRoot, "src/theme/orbTokens.css"), "utf8");
const markSvg = readFileSync(resolve(webRoot, "public/brand/orb/opal-orb-mark.svg"), "utf8");
const wordmarkSvg = readFileSync(resolve(webRoot, "public/brand/orb/opal-orb-wordmark.svg"), "utf8");

function occurrences(haystack: string, needle: string): number {
  return haystack.split(needle).length - 1;
}

describe("orb provenance - tokens are the sampled values", () => {
  it("fire peaks, ring metal, points, field match orbSampled.json", () => {
    expect(ORB_SAMPLED.fireVioletPeak).toBe(sampled.fire.violet.peakHex);
    expect(ORB_SAMPLED.fireBluePeak).toBe(sampled.fire.blue.peakHex);
    expect(ORB_SAMPLED.fireCyanPeak).toBe(sampled.fire.cyan.peakHex);
    expect(ORB_SAMPLED.fireMagentaPeak).toBe(sampled.fire.magenta.peakHex);
    expect(ORB_SAMPLED.fireGoldPeak).toBe(sampled.fire.gold.peakHex);
    expect(ORB_SAMPLED.fireGoldCore).toBe(sampled.fire.gold.coreHex);
    expect(ORB_SAMPLED.ringMetal).toBe(sampled.ringMetal.median);
    expect(ORB_SAMPLED.ringMetalLit).toBe(sampled.ringMetal.p90);
    expect(ORB_SAMPLED.pointsOfLight).toBe(sampled.pointsOfLight.median);
    expect(ORB_SAMPLED.fieldOrb).toBe(sampled.field.orb);
    expect(ORB_SAMPLED.fieldWordmark).toBe(sampled.field.wordmark);
    expect([...ORB_SAMPLED.wordmarkGradient]).toEqual(sampled.wordmark.gradientSlices);
  });

  it("CSS primitives carry the same sampled hexes", () => {
    for (const hex of [
      sampled.fire.violet.peakHex,
      sampled.fire.blue.peakHex,
      sampled.fire.cyan.peakHex,
      sampled.fire.magenta.peakHex,
      sampled.fire.gold.peakHex,
      sampled.fire.gold.coreHex,
      sampled.ringMetal.median,
      sampled.ringMetal.p90,
      sampled.pointsOfLight.median,
    ]) {
      expect(css.toLowerCase()).toContain(hex.toLowerCase());
    }
    for (const hex of sampled.wordmark.gradientSlices) {
      expect(css.toLowerCase()).toContain(hex.toLowerCase());
    }
  });

  it("sampled geometry record matches orbGeometry constants", () => {
    expect(sampled.orbGeometry.sphereCenter).toEqual([810, 800]);
    expect(sampled.orbGeometry.sphereRadius).toBe(410);
    expect(ORB_SPHERE).toEqual({ cx: 101, cy: 100, r: 51 });
    expect(ORB_RING.r).toBe(71);
    expect(sampled.orbGeometry.ringRadius).toBe(568);
  });
});

describe("indicator language - canon wins, mode-invariant (MP-11)", () => {
  it("ORB_INDICATOR equals the canonical pinned hexes and PLAN_STATE_HEX", () => {
    expect(ORB_INDICATOR).toEqual({
      forming: "#8B5CF6",
      happening: "#00E5FF",
      ready: "#FFC86B",
      action: "#FF4D5E",
      past: "#FFFFFF",
    });
    expect(ORB_INDICATOR.forming).toBe(PLAN_STATE_HEX.forming);
    expect(ORB_INDICATOR.happening).toBe(PLAN_STATE_HEX.happening);
    expect(ORB_INDICATOR.ready).toBe(PLAN_STATE_HEX.ready);
    expect(ORB_INDICATOR.action).toBe(PLAN_STATE_HEX.action);
    expect(ORB_INDICATOR.past).toBe(PLAN_STATE_HEX.past);
  });

  it("each --orb-indicator-* hue is defined exactly once in the CSS (no per-mode drift)", () => {
    for (const token of [
      "--orb-indicator-forming",
      "--orb-indicator-happening",
      "--orb-indicator-ready",
      "--orb-indicator-action",
      "--orb-indicator-past",
    ]) {
      expect(occurrences(css, `${token}:`), token).toBe(1);
    }
    expect(css).toContain("--orb-indicator-forming: #8b5cf6");
    expect(css).toContain("--orb-indicator-happening: #00e5ff");
    expect(css).toContain("--orb-indicator-ready: #ffc86b");
    expect(css).toContain("--orb-indicator-action: #ff4d5e");
    expect(css).toContain("--orb-indicator-past: #ffffff");
  });

  it("past has no glow in either mode (the stone at rest)", () => {
    expect(occurrences(css, "--orb-indicator-past-glow: transparent")).toBe(2);
  });

  it("AT-02: every --state-* in c2Tokens.css resolves to its canon value in both modes", () => {
    // The divergent second hue family is dead: each --state-* token
    // (light block AND dark block) is an alias of the canon
    // --orb-indicator-* token, whose single definition above equals
    // PLAN_STATE_HEX. No derivative state hex may reappear.
    const c2 = readFileSync(resolve(webRoot, "src/theme/c2Tokens.css"), "utf8");
    for (const family of ["forming", "action", "ready", "happening", "past"] as const) {
      expect(
        occurrences(c2, `--state-${family}: var(--orb-indicator-${family})`),
        `--state-${family} alias (light + dark)`,
      ).toBe(2);
      expect(PLAN_STATE_HEX[family]).toBe(ORB_INDICATOR[family]);
    }
    for (const dead of ["#6d5df0", "#9d94ff", "#e8323f", "#ff7a85", "#b77900", "#f5b93f", "#0a7c6e", "#4adecb"]) {
      expect(c2.toLowerCase()).not.toContain(dead);
    }
  });

  it("sampled state anchors are recorded as provenance, not used as indicators", () => {
    expect(ORB_SAMPLED.sampledState.formingVioletMedian).toBe(sampled.fire.violet.hex);
    expect(ORB_SAMPLED.sampledState.happeningCyanMedian).toBe(sampled.fire.cyan.hex);
    expect(ORB_SAMPLED.sampledState.readyGoldMedian).toBe(sampled.fire.gold.hex);
    expect(ORB_SAMPLED.sampledState.actionRedOrangeMedian).toBe(sampled.fire.redOrange.hex);
    expect(ORB_INDICATOR.forming.toLowerCase()).not.toBe(sampled.fire.violet.hex);
  });
});

describe("standalone reductions carry the same geometry + sampled fills", () => {
  it("mark svg: measured sphere/ring + sampled gradient stops", () => {
    expect(markSvg).toContain('cx="101" cy="100" r="51"');
    expect(markSvg).toContain('cx="101" cy="100" r="71"');
    expect(markSvg).toContain('cx="101" cy="106" rx="86" ry="11"');
    for (const hex of ["#7d4dce", "#6257c7", "#60b9d8", "#d972c2", "#f1aa62", "#dbae8e", "#ffeac9", "#fff1d0"]) {
      expect(markSvg).toContain(hex);
    }
  });

  it("wordmark svg: gem facets + letter paths + userSpaceOnUse gradient", () => {
    expect(wordmarkSvg).toContain('gradientUnits="userSpaceOnUse"');
    expect(wordmarkSvg).toContain(WM_PATHS.p);
    expect(wordmarkSvg).toContain(WM_PATHS.a);
    expect(wordmarkSvg).toContain(WM_PATHS.l);
    for (const f of GEM_O_FACETS) {
      expect(wordmarkSvg).toContain(f.fill);
    }
    for (const hex of sampled.wordmark.gradientSlices) {
      expect(wordmarkSvg.toLowerCase()).toContain(hex.toLowerCase());
    }
  });
});

describe("AR-F1 ignition - the lit frame is an event (R19 W27 AT-04)", () => {
  const orbCss = readFileSync(resolve(webRoot, "src/brand/orb/orb.css"), "utf8");
  it("one ignition on mount: travel 600ms + bloom settling at 900ms, once, never a loop", () => {
    expect(orbCss).toContain("animation: orb-fire-ignite 900ms");
    expect(orbCss).toContain("animation: orb-fire-ignite-travel 600ms");
    expect(orbCss).toContain("@keyframes orb-fire-ignite-travel");
    // the bloom's last keyframe IS the resting shadow (settle, no snap)
    expect(orbCss).toContain("box-shadow: var(--orb-fire-glow);");
    expect(orbCss).not.toMatch(/orb-fire-ignite[^{]*infinite/);
  });
  it("past never ignites, and reduced motion kills the motion only (resting glow stays)", () => {
    expect(orbCss).toContain('.orb-fire-frame[data-orb-state="past"]');
    const rm = orbCss.slice(orbCss.indexOf("@media (prefers-reduced-motion: reduce)", orbCss.indexOf("orb-fire-ignite")));
    expect(rm).toContain(".orb-fire-frame");
    expect(rm).toContain("animation: none");
  });
});

describe("hero assets - the master itself, keyed", () => {
  it("hero + medallion WebPs exist and are real WebP with substance", () => {
    for (const path of [ORB_ASSETS.hero, ORB_ASSETS.hero512, ORB_ASSETS.medallion]) {
      const full = resolve(webRoot, "public", path.replace(/^\//, ""));
      const buf = readFileSync(full);
      expect(buf.subarray(0, 4).toString("ascii")).toBe("RIFF");
      expect(buf.subarray(8, 12).toString("ascii")).toBe("WEBP");
      expect(statSync(full).size).toBeGreaterThan(50_000);
    }
  });
});

(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
let host: HTMLDivElement | null = null;
let root: Root | null = null;
async function render(node: React.ReactNode) {
  host = document.createElement("div");
  document.body.appendChild(host);
  root = createRoot(host);
  await act(async () => {
    root!.render(node);
  });
  return host;
}
afterEach(async () => {
  if (root) await act(async () => root!.unmount());
  host?.remove();
  host = null;
  root = null;
  document.body.innerHTML = "";
  document.documentElement.removeAttribute("data-mode");
});

describe("orb components - right asset per job", () => {
  it("hero in dark mode is the keyed master; in light the medallion variant", async () => {
    document.documentElement.setAttribute("data-mode", "dark");
    await render(<OrbHero size={300} title="" />);
    let img = document.querySelector("img");
    expect(img?.getAttribute("src")).toBe(ORB_ASSETS.hero512);
    expect(img?.getAttribute("data-orb-asset")).toBe("hero-master");
    document.documentElement.setAttribute("data-mode", "light");
    await render(<OrbHero size={300} title="" />);
    img = document.querySelector("img");
    expect(img?.getAttribute("src")).toBe(ORB_ASSETS.medallion);
    expect(img?.getAttribute("data-orb-asset")).toBe("hero-medallion");
  });

  it("mark renders the ring device; below 24px the small reduction", async () => {
    await render(
      <>
        <OrbMark size={40} />
        <OrbMark size={16} />
        <OrbMarkMono size={24} />
      </>,
    );
    expect(document.querySelector('[data-orb-asset="mark"]')).toBeTruthy();
    expect(document.querySelector('[data-orb-asset="mark-small"]')).toBeTruthy();
    expect(document.querySelector('[data-orb-asset="mark-mono"]')).toBeTruthy();
  });

  it("wordmark reduction reads OPAL with the faceted gem O", async () => {
    await render(<OrbWordmark width={200} />);
    const svg = document.querySelector('[data-orb-asset="wordmark"]');
    expect(svg?.getAttribute("aria-label")).toBe("OPAL");
    expect(svg?.querySelectorAll("polygon").length).toBe(12);
  });

  it("state stone: past rests, happening glows; unknown falls to forming", async () => {
    await render(
      <>
        <StateStone state="past" />
        <StateStone state="happening" />
        <StateStone state="mystery" />
      </>,
    );
    const stones = document.querySelectorAll('[data-orb="state-stone"]');
    expect(stones[0]?.getAttribute("data-orb-state")).toBe("past");
    expect(stones[1]?.getAttribute("data-orb-state")).toBe("happening");
    expect(stones[2]?.getAttribute("data-orb-state")).toBe("forming");
    expect(stones[2]?.getAttribute("data-orb-state-known")).toBe("0");
  });

  it("AT-14: the stone carries a non-color pattern channel per family", async () => {
    await render(
      <>
        <StateStone state="forming" />
        <StateStone state="action" />
        <StateStone state="ready" />
        <StateStone state="happening" />
        <StateStone state="past" />
      </>,
    );
    const stones = document.querySelectorAll('[data-orb="state-stone"]');
    expect([...stones].map((s) => s.getAttribute("data-stone-pattern"))).toEqual([
      "dashed",
      "weight",
      "solid",
      "double",
      "rest",
    ]);
    // forming's ring is really dashed; action's is really heavier;
    // happening really grows a second ring.
    const rings = [...stones].map((s) => s.querySelectorAll("circle"));
    expect(rings[0]?.[2]?.getAttribute("stroke-dasharray")).toBe("7 6");
    expect(rings[1]?.[2]?.getAttribute("stroke-width")).toBe("17");
    expect(rings[3]?.length).toBe(4);
    expect(rings[4]?.length).toBe(2);
  });

  it("fire frame carries its state for the tinted glow", async () => {
    await render(
      <FireFrame state="action">
        <p>Needs you</p>
      </FireFrame>,
    );
    const frame = document.querySelector('[data-orb="fire-frame"]');
    expect(frame?.getAttribute("data-orb-state")).toBe("action");
    expect(frame?.textContent).toContain("Needs you");
  });
});

describe("harmony-0: lockup law + interim-mark retirement (founder 2026-10-18 12:53/12:54 PDT)", () => {
  it("the interim mark is retired: no alternate export exists in the orb system", () => {
    expect((OrbModule as Record<string, unknown>).OrbMarkAlternate).toBeUndefined();
  });

  it("the combined lockup is STACKED (orb above wordmark); wordmark form is one element alone", async () => {
    const rootEl = document.createElement("div");
    document.body.appendChild(rootEl);
    const root: Root = createRoot(rootEl);
    await act(async () => {
      root.render(<OrbLockup wordmarkWidth={90} />);
    });
    const stacked = rootEl.querySelector('[data-orb-lockup="stacked"]');
    expect(stacked).not.toBeNull();
    expect(stacked?.className).toContain("orb-lockup--stacked");
    expect(rootEl.querySelector('[data-orb-lockup="full"]')).toBeNull();
    await act(async () => {
      root.render(<OrbLockup form="wordmark" wordmarkWidth={72} />);
    });
    const alone = rootEl.querySelector('[data-orb-lockup="wordmark"]');
    expect(alone).not.toBeNull();
    expect(alone?.querySelector('[data-orb-asset="mark"]')).toBeNull();
    await act(async () => root.unmount());
    rootEl.remove();
  });
});
